insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('e5281aa6-cb6a-494e-aecf-cd5dae3b23b0', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', null, 'topic'::public.curated_course_node_type, 'Foundations of Pharmacology and Medication Use', 'This opening section gives students the vocabulary and workflow map they need before studying individual drug classes. The aim is to see medications as regulated tools used within clinical systems, not just lists of names to memorize.', 0),
  ('bfb1a402-cda5-4c80-be6c-e2b59eb12d6a', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'e5281aa6-cb6a-494e-aecf-cd5dae3b23b0', 'subtopic'::public.curated_course_node_type, 'Core Medication Vocabulary', 'Students learn the basic terms used by clinicians, pharmacists, labels, and drug references.', 0),
  ('f155f25a-2e86-4078-a6e9-e20d3ee804aa', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'bfb1a402-cda5-4c80-be6c-e2b59eb12d6a', 'concept'::public.curated_course_node_type, 'Drug, medication, pharmacology, pharmacotherapy, indication, contraindication, precaution, warning, boxed warning', null, 0),
  ('181cabdc-afe6-4e19-953d-ba475027dfda', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'bfb1a402-cda5-4c80-be6c-e2b59eb12d6a', 'concept'::public.curated_course_node_type, 'Generic name, brand name, chemical name, therapeutic class, pharmacologic class, prototype drug', null, 1),
  ('a1470612-67ca-4c9d-9ee1-a28d0b987a91', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'bfb1a402-cda5-4c80-be6c-e2b59eb12d6a', 'concept'::public.curated_course_node_type, 'Prescription drugs, OTC drugs, supplements, biologics, biosimilars, vaccines, controlled substances', null, 2),
  ('f8123944-c61e-49f0-af11-dc5424853e9c', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'bfb1a402-cda5-4c80-be6c-e2b59eb12d6a', 'concept'::public.curated_course_node_type, 'Therapeutic effect, side effect, adverse drug reaction, toxicity, therapeutic index, narrow therapeutic index', null, 3),
