  ('efec6c6e-a7b4-45be-9001-ead5f81cef13', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '15a4d2b1-3ba4-47ec-ac14-d007474515b1', 'concept'::public.curated_course_node_type, 'Medication order, prescription, e-prescribing, formulary, prior authorization, refill, medication list, discharge prescription', null, 2),
  ('87f82278-29d7-4181-950c-fc862dcd9b3d', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '15a4d2b1-3ba4-47ec-ac14-d007474515b1', 'concept'::public.curated_course_node_type, 'Start, stop, hold, taper, titrate, switch, substitute, renew, discontinue, and deprescribe', null, 3),
