  ('86e7e94a-44ee-4315-b8d7-ea12478685cb', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '2160a119-b998-42aa-a60d-12c2685b7f11', 'concept'::public.curated_course_node_type, 'Efficacy, effectiveness, safety, benefit-risk assessment, vulnerable populations, and real-world evidence', null, 2),
  ('3593ebd9-7564-4fb9-a016-72be17b6a706', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '2160a119-b998-42aa-a60d-12c2685b7f11', 'concept'::public.curated_course_node_type, 'Generic substitution, therapeutic equivalence, Orange Book, bioequivalence, and medication quality standards', null, 3),
  ('af021ccc-daf8-453b-a72f-23949d44a2f5', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', null, 'topic'::public.curated_course_node_type, 'Pharmacokinetics: Absorption, Distribution, Metabolism, and Excretion', 'Pharmacokinetics explains what the body does to a drug. Students learn how drug levels rise, move, transform, and leave the body, and why this matters for timing, dosing, and toxicity.', 1),
  ('265d0de5-ef18-43d4-883a-6b08ecb2c2de', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'af021ccc-daf8-453b-a72f-23949d44a2f5', 'subtopic'::public.curated_course_node_type, 'Absorption and Bioavailability', 'Students connect route, formulation, and physiology to how much drug reaches systemic circulation.', 0),
  ('3fef6509-5b0d-424f-a8b5-e13a34a4db19', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '265d0de5-ef18-43d4-883a-6b08ecb2c2de', 'concept'::public.curated_course_node_type, 'Absorption, bioavailability, first-pass metabolism, onset, peak, duration, Cmax, Tmax, area under the curve', null, 0),
  ('4520f278-b10d-4346-8fbc-fcae1848557c', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '265d0de5-ef18-43d4-883a-6b08ecb2c2de', 'concept'::public.curated_course_node_type, 'Oral, sublingual, buccal, rectal, inhaled, topical, transdermal, subcutaneous, intramuscular, intravenous routes', null, 1),
  ('74856e3d-30c4-4c4d-a867-70065ebefc97', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '265d0de5-ef18-43d4-883a-6b08ecb2c2de', 'concept'::public.curated_course_node_type, 'Food effects, gastric pH, gastric emptying, intestinal motility, drug solubility, transporters, and formulation design', null, 2),
  ('349fa1a1-f338-49e2-988f-4ae4d46eaf1c', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '265d0de5-ef18-43d4-883a-6b08ecb2c2de', 'concept'::public.curated_course_node_type, 'Immediate-release, delayed-release, enteric-coated, extended-release, depot, patch, inhaler, and injectable preparations', null, 3),
  ('2cee3b63-be4f-46fd-aac5-2157e4dc6510', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'af021ccc-daf8-453b-a72f-23949d44a2f5', 'subtopic'::public.curated_course_node_type, 'Distribution and Protein Binding', 'Students learn why drugs do not spread evenly through the body and why patient factors change drug effect.', 1),
