  ('b980d2bb-fa17-45fb-9d99-058fe77e527c', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '2cee3b63-be4f-46fd-aac5-2157e4dc6510', 'concept'::public.curated_course_node_type, 'Blood-brain barrier, placenta, adipose tissue, body water, perfusion, edema, and dehydration', null, 1),
  ('06f1abd4-cbeb-4acd-bb58-dc4a25a67733', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '2cee3b63-be4f-46fd-aac5-2157e4dc6510', 'concept'::public.curated_course_node_type, 'Highly protein-bound drugs, displacement interactions, hypoalbuminemia, and critical illness', null, 2),
  ('65981f48-123f-46b3-93c8-795e79a8a614', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '2cee3b63-be4f-46fd-aac5-2157e4dc6510', 'concept'::public.curated_course_node_type, 'Loading dose, target concentration, tissue penetration, and site of action', null, 3),
  ('b8f68ca4-d449-4f2e-85ba-6808c35760bc', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'af021ccc-daf8-453b-a72f-23949d44a2f5', 'subtopic'::public.curated_course_node_type, 'Metabolism, Excretion, Half-Life, and Steady State', 'Students learn why liver and kidney function are central to safe medication use.', 2),
  ('2cdb809c-11fc-4667-961e-38a8a70c47d3', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'b8f68ca4-d449-4f2e-85ba-6808c35760bc', 'concept'::public.curated_course_node_type, 'Metabolism, biotransformation, active metabolite, prodrug, Phase I, Phase II, cytochrome P450', null, 0),
