  ('0c7e88d8-0c2b-4305-ab2f-d6968cfaf0c8', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'b8f68ca4-d449-4f2e-85ba-6808c35760bc', 'concept'::public.curated_course_node_type, 'Half-life, steady state, accumulation, maintenance dose, dose interval, trough, peak, washout period', null, 2),
  ('8e5f16f2-992c-4d3a-8c59-4e7f16b8f9c5', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'b8f68ca4-d449-4f2e-85ba-6808c35760bc', 'concept'::public.curated_course_node_type, 'Renal impairment, hepatic impairment, creatinine clearance, eGFR, dose adjustment, and therapeutic drug monitoring', null, 3),
  ('97e8f431-89f6-4688-9132-b59850d02d81', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', null, 'topic'::public.curated_course_node_type, 'Pharmacodynamics: Receptors, Dose-Response, Potency, and Efficacy', 'Pharmacodynamics explains what a drug does to the body. Students learn how drugs interact with targets and why dose changes can improve benefit or increase harm.', 2),
  ('c6e4abf0-5bf0-445d-9233-784a82cefdf0', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '97e8f431-89f6-4688-9132-b59850d02d81', 'subtopic'::public.curated_course_node_type, 'Drug Targets and Receptor Concepts', 'Students learn the molecular vocabulary behind drug effects without losing the clinical purpose.', 0),
  ('e3684f2a-f063-4c07-92f0-35164ce757c1', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'c6e4abf0-5bf0-445d-9233-784a82cefdf0', 'concept'::public.curated_course_node_type, 'Receptor, ligand, binding site, affinity, intrinsic activity, selectivity, specificity', null, 0),
  ('6e1ee6d2-da01-4e5c-906e-7c4b456a443c', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'c6e4abf0-5bf0-445d-9233-784a82cefdf0', 'concept'::public.curated_course_node_type, 'Agonist, antagonist, partial agonist, inverse agonist, competitive antagonist, noncompetitive antagonist', null, 1),
  ('252e1802-612d-4169-aa2d-c5bdd393a146', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'c6e4abf0-5bf0-445d-9233-784a82cefdf0', 'concept'::public.curated_course_node_type, 'Ion channels, enzymes, transporters, receptors, G-protein coupled receptors, nuclear receptors, and monoclonal antibodies', null, 2),
  ('7d5e0adc-b13a-4dbb-864f-58a16841d9eb', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'c6e4abf0-5bf0-445d-9233-784a82cefdf0', 'concept'::public.curated_course_node_type, 'Upregulation, downregulation, desensitization, tachyphylaxis, tolerance, dependence, and withdrawal', null, 3),
  ('d6d69906-4f83-4c71-a146-2609594fdd57', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '97e8f431-89f6-4688-9132-b59850d02d81', 'subtopic'::public.curated_course_node_type, 'Dose-Response Relationships', 'Students learn to interpret how response changes as dose changes and why more drug is not always better.', 1),
  ('330adadd-67bb-40a8-93ab-3da43df202ca', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'd6d69906-4f83-4c71-a146-2609594fdd57', 'concept'::public.curated_course_node_type, 'Dose-response curve, graded response, quantal response, threshold dose, maximal effect, plateau', null, 0);
