  ('1f72df8d-fa5e-428f-aed9-7390f57dd95e', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', null, 'topic'::public.curated_course_node_type, 'Dosage Forms, Routes of Administration, and Basic Dose Calculations', 'This section links medication math and dosage forms to safety. Students practice the kinds of calculations and route decisions that prevent avoidable harm.', 3),
