  ('b1d91e6d-acc3-4034-9d10-5710f027506e', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '3c56997f-57b3-4b39-870d-8a01a1d739f7', 'concept'::public.curated_course_node_type, 'Crushing restrictions, enteric coating, extended release, dose dumping, line flushing, and administration technique', null, 3),
  ('447d9e27-441d-4389-b14c-14ddbdcf37e5', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '1f72df8d-fa5e-428f-aed9-7390f57dd95e', 'subtopic'::public.curated_course_node_type, 'Foundational Dose Calculations', 'Students build confidence with common medication math and learn to pause when a result is unreasonable.', 1),
