  ('a812e84c-96e4-4c10-a10b-b95087c449ad', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '447d9e27-441d-4389-b14c-14ddbdcf37e5', 'concept'::public.curated_course_node_type, 'IV flow rate, mL/hr, drops/min, infusion time, concentration per mL, and pump programming checks', null, 3),
