  ('6aadae18-d6f6-48c7-8ce5-e6f5f9e06656', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '80383990-982e-42db-8b91-b8401550481d', 'concept'::public.curated_course_node_type, 'Allergies, renal function, hepatic function, vital signs, laboratory values, and indication check before administration', null, 2),
  ('0c5ecbb0-8917-4a62-b4bd-e3a40106596f', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '80383990-982e-42db-8b91-b8401550481d', 'concept'::public.curated_course_node_type, 'Hold parameters, maximum daily dose, therapeutic range, escalation to prescriber or pharmacist, and documentation', null, 3),
  ('19e1bfa5-1d86-471d-88c2-eb5d63d7b2eb', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', null, 'topic'::public.curated_course_node_type, 'Medication Safety, The Rights of Administration, Reconciliation, and Error Prevention', 'Medication safety is a systems skill. This section teaches students to use standardized checks, team communication, and reconciliation to reduce harm.', 4),
