  ('843b0945-b72a-4a3f-96e7-056c4f6bd11f', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'd9174936-bfc2-40ac-9a22-4d78f979fdc7', 'concept'::public.curated_course_node_type, 'Right patient, right medication, right dose, right route, right time, right documentation', null, 0),
