  ('63fd74c4-17fc-4905-b195-095e4143c5c4', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'd9174936-bfc2-40ac-9a22-4d78f979fdc7', 'concept'::public.curated_course_node_type, 'Patient identifiers, barcode medication administration, allergy band, MAR, eMAR, and order verification', null, 2),
