  ('cee4ee53-1525-4bd0-8837-aa09820192ec', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '3316e5cd-cc5f-4cd5-bdbd-59e7ecb8d95f', 'concept'::public.curated_course_node_type, 'Patient interview, caregiver input, pharmacy fill history, pill bottles, discharge summary, and primary care record', null, 3),
  ('0adce517-4237-4de7-89ef-9a59c47ee8db', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '19e1bfa5-1d86-471d-88c2-eb5d63d7b2eb', 'subtopic'::public.curated_course_node_type, 'Error Prevention and Safety Culture', 'This subtopic shows how well-designed systems catch mistakes before they reach patients.', 2),
