insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('9cd0a617-3ffb-4695-8236-4ff25a35ec01', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', null, 'topic'::public.curated_course_node_type, 'Drug Information Literacy: Labels, References, Evidence, and Patient-Friendly Sources', 'Students need reliable medication information more than memorized trivia. This section teaches them where to look, what to verify, and how to translate technical information for patient care.', 5),
  ('b4508b7e-6c34-4b35-8f4f-2601974143f5', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '9cd0a617-3ffb-4695-8236-4ff25a35ec01', 'subtopic'::public.curated_course_node_type, 'Reading Drug Labels and Monographs', 'Students learn to pull essential safety and use information from official and clinical references.', 0),
  ('6d61eac7-3daa-4ad2-8b5e-5d3a560aebc7', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'b4508b7e-6c34-4b35-8f4f-2601974143f5', 'concept'::public.curated_course_node_type, 'Indications, dosage and administration, contraindications, warnings, precautions, adverse reactions, interactions', null, 0),
