  ('b0e36502-4228-489a-ab46-538b413f78ee', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'b4508b7e-6c34-4b35-8f4f-2601974143f5', 'concept'::public.curated_course_node_type, 'Dosage forms and strengths, storage, handling, patient counseling information, medication guide, and instructions for use', null, 2),
  ('bc6c7855-ea67-484a-840d-3604189339f3', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', 'b4508b7e-6c34-4b35-8f4f-2601974143f5', 'concept'::public.curated_course_node_type, 'DailyMed, FDA labels, drug guide, package insert, professional monograph, and patient leaflet', null, 3),
