  ('e6576e18-0a5f-40d2-9b00-89f94e1069a9', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '3231bacd-6f24-4207-b7d7-9c19d788219b', 'concept'::public.curated_course_node_type, 'FDA, DailyMed, MedlinePlus, CDC, ISMP, Merck Manual, professional society guidelines, and institutional protocols', null, 2),
  ('af0c35f1-18f2-4d0a-90ed-9287c045c264', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '3231bacd-6f24-4207-b7d7-9c19d788219b', 'concept'::public.curated_course_node_type, 'Advertisement, anecdote, influencer content, supplement marketing, misinformation, and unsupported off-label claims', null, 3),
  ('1cd4ac7d-a981-444f-aa1e-80573c830049', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '9cd0a617-3ffb-4695-8236-4ff25a35ec01', 'subtopic'::public.curated_course_node_type, 'Using Evidence for Medication Decisions', 'Students practice asking evidence-based questions without needing advanced research training.', 2),
