  ('323a57db-c5b4-4f41-a43e-56f6486473d1', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '1cd4ac7d-a981-444f-aa1e-80573c830049', 'concept'::public.curated_course_node_type, 'Clinical significance, statistical significance, surrogate outcome, patient-oriented outcome, and real-world applicability', null, 3),
  ('4b816611-3375-4efc-a80c-835e2df1a5d3', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', null, 'topic'::public.curated_course_node_type, 'Autonomic Nervous System Pharmacology', 'Autonomic pharmacology becomes much easier when students connect drugs to sympathetic and parasympathetic physiology. This section provides that map.', 6),
