  ('065f0db5-0f4f-40c4-8934-0f0b9dc210c5', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', null, 'topic'::public.curated_course_node_type, 'Anti-Inflammatory, Immune, Cancer, and Toxicology Foundations', 'This section introduces medications that alter inflammation, immunity, and cell growth, plus the basics of toxic exposures and antidotes.', 11),
  ('75997255-bcc7-494a-b2a7-5c33955194cc', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '065f0db5-0f4f-40c4-8934-0f0b9dc210c5', 'subtopic'::public.curated_course_node_type, 'Anti-Inflammatory and Immune-Modifying Drugs', 'Students learn how inflammation can be reduced and why immune suppression requires careful monitoring.', 0),
  ('b40ea501-69ec-41f9-844c-56e907963b53', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '75997255-bcc7-494a-b2a7-5c33955194cc', 'concept'::public.curated_course_node_type, 'NSAIDs, corticosteroids, disease-modifying antirheumatic drugs, biologics, monoclonal antibodies, immunosuppressants', null, 0),
