  ('ae2265e4-f44e-43cd-8007-6bb6058a3bb8', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '75997255-bcc7-494a-b2a7-5c33955194cc', 'concept'::public.curated_course_node_type, 'Prednisone, methotrexate, TNF inhibitors, calcineurin inhibitors, antihistamines, and leukotriene modifiers', null, 3),
