  ('8aaa9d60-b30a-4a85-a416-4a80fa082da9', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '5992b634-2a2e-4956-b220-bcf65389d051', 'concept'::public.curated_course_node_type, 'Airway, breathing, circulation, vital signs, mental status, ECG, labs, timing of ingestion, and safety reporting', null, 3),
