  ('b12bec68-bf75-4027-86b2-e9ccb34f1b2b', 'c8f2a1d6-4e37-4b09-9c15-7a0d3e6b5f82', '9eddd19f-e4e3-43f8-bf44-df1841d986ff', 'concept'::public.curated_course_node_type, 'Start low and go slow, dose forms, adherence support, caregiver education, and medication storage safety', null, 3),
